from datetime import date, timedelta


def next_business_day(day, holidays=()):
    """First weekday STRICTLY AFTER `day` (ISO date string) that is neither a
    Saturday/Sunday nor listed in `holidays` (an iterable of ISO strings).
    Returns an ISO date string."""
    current = date.fromisoformat(day) + timedelta(days=1)
    skip = set(holidays)
    while current.weekday() >= 5 or current.isoformat() in skip:
        current += timedelta(days=1)
    return current.isoformat()

