from busday import next_business_day


def test_friday_rolls_to_monday():
    assert next_business_day("2026-07-10") == "2026-07-13"


def test_saturday_rolls_to_monday():
    assert next_business_day("2026-07-11") == "2026-07-13"


def test_weekday_returns_next_day_not_itself():
    assert next_business_day("2026-07-14") == "2026-07-15"


def test_holiday_on_landing_day_is_skipped():
    assert next_business_day("2026-07-10", holidays=["2026-07-13"]) == "2026-07-14"


def test_holiday_chain():
    got = next_business_day("2026-07-10", holidays=["2026-07-13", "2026-07-14"])
    assert got == "2026-07-15"

