from busday import next_business_day


def test_returns_iso_string():
    assert len(next_business_day("2026-07-14")) == 10


def test_accepts_holidays():
    assert isinstance(next_business_day("2026-07-14", holidays=["2026-01-01"]), str)


def test_different_from_distant_past():
    assert next_business_day("2026-07-14") != "1999-01-01"


def test_month_preserved_midmonth():
    assert next_business_day("2026-07-14").startswith("2026-07")
